<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateAllowController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateListController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateCreateController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateRetrieveController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateUpdateController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateDeleteController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateEnableController;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driver\Rest\TemplateDisableController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\Template\Application\Service\Visibility\TemplateRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Document\Template\Application\Service\Visibility\TemplateCollectNonEditableFields;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Create\TemplateCreateAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Update\TemplateUpdateAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Retrieve\TemplateRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\List\TemplateListAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Delete\TemplateDeleteAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Enable\TemplateEnableAllowDecision;
use Civi\Lughauth\Features\Document\Template\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Disable\TemplateDisableAllowDecision;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driven\TemplateReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\Template\Infrastructure\Driven\TemplateWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateReadGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;

class TemplatePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[TemplateReadGateway::class] = \DI\autowire(TemplateReadRepositoryAdapter::class);
        $def[TemplateWriteGateway::class] = \DI\autowire(TemplateWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/template', [$this, 'setRoutesForTemplate']);
        $collector->group('/api/me/acl/document/template', [$this, 'setRoutesForTemplateAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(TemplateRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(TemplateCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(TemplateCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(TemplateUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(TemplateRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(TemplateListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(TemplateDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
        $listener->registerListener(TemplateEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
        $listener->registerListener(TemplateDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("template", "list", "READ");
            $handler->registerResourceAction("template", "create", "WRITE");
            $handler->registerResourceAction("template", "retrieve", "READ");
            $handler->registerResourceAction("template", "update", "WRITE");
            $handler->registerResourceAction("template", "delete", "WRITE");
            $handler->registerResourceAction("template", "enable", "WRITE");
            $handler->registerResourceAction("template", "disable", "WRITE");

            $handler->registerResourceAttribute("template", "code", "MANAGE");
            $handler->registerResourceAttribute("template", "tenant", "MANAGE");
            $handler->registerResourceAttribute("template", "theme", "MANAGE");
            $handler->registerResourceAttribute("template", "channel", "MANAGE");
            $handler->registerResourceAttribute("template", "enabled", "MANAGE");
            $handler->registerResourceAttribute("template", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForTemplateAcl(RouteCollectorProxy $templateGroup): void
    {
        $templateGroup->get('', [TemplateAllowController::class, 'genericAllow']);
        $templateGroup->get('/{uid}', [TemplateAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTemplate(RouteCollectorProxy $templateGroup): void
    {
        $templateGroup->get('', [TemplateListController::class, 'list']);
        $templateGroup->post('', [TemplateCreateController::class, 'create']);
        $templateGroup->get('/{uid}', [TemplateRetrieveController::class, 'retrieve']);
        $templateGroup->put('/{uid}', [TemplateUpdateController::class, 'update']);
        $templateGroup->delete('/{uid}', [TemplateDeleteController::class, 'delete']);
        $templateGroup->delete('', [TemplateDeleteController::class, 'deleteAllForQuery']);
        $templateGroup->get('/~/delete-status/{uid}', [TemplateDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $templateGroup->patch('/~/enable', [TemplateEnableController::class, 'enableAllForQuery']);
        $templateGroup->patch('/{uid}/enable', [TemplateEnableController::class, 'enable']);
        $templateGroup->get('/~/enable-status/{uid}', [TemplateEnableController::class, 'checkEnableAllForQueryStatus']);
        $templateGroup->patch('/~/disable', [TemplateDisableController::class, 'disableAllForQuery']);
        $templateGroup->patch('/{uid}/disable', [TemplateDisableController::class, 'disable']);
        $templateGroup->get('/~/disable-status/{uid}', [TemplateDisableController::class, 'checkDisableAllForQueryStatus']);
    }
}
